\begin{align*} P(x) &= \sum_{k=0}^{2} \binom{2}{k} \mathfrak{X}^{2-k} \vartheta^{k} \\ &\equiv \mathcal{O} \left[ \mathbb{H} \right] \end{align}
rather,
